  async function clientRoute(request:any,reply:any,operation:()=>Promise<unknown>,successCode=200){try{const result=await operation();return reply.sent?result:reply.code(successCode).send(result);}catch(error){if(error instanceof DomainError){if(/^\/api\/v1\/(invoices|payments|expenses|projects\/[^/]+\/financial-summary)/.test(request.url)){const actions:Partial<Record<DomainError["code"],string>>={FORBIDDEN:"finance.permission_denied",VERSION_CONFLICT:"finance.version_conflict",ENTITY_ARCHIVED:"finance.archived_mutation_denied",INVALID_STATUS_TRANSITION:"finance.invalid_lifecycle_transition",INVALID_RELATIONSHIP:"finance.invalid_relationship"};const action=actions[error.code];if(action)await audit(request.claims?.tenantId,request.claims?.sub,action,"finance",request.params?.id,request.id,{method:request.method,url:request.url,code:error.code,details:error.details});}return reply.code(error.statusCode).send({error:{code:error.code,message:error.message,details:error.details,correlationId:String(request.headers["x-correlation-id"]??request.id)}});}if(error instanceof Error&&error.name==="ZodError")return reply.code(400).send({error:{code:"VALIDATION_ERROR",message:"Invalid request",details:{},correlationId:String(request.headers["x-correlation-id"]??request.id)}});request.log.error({err:error},"client route failed");return reply.code(500).send({error:{code:"INTERNAL_ERROR",message:"Internal server error",details:{},correlationId:String(request.headers["x-correlation-id"]??request.id)}});}}
  async function audit(tenantId:string|undefined, actorId:string|undefined, action:string, entityType:string, entityId:string|undefined, requestId:string, metadata:Record<string,unknown>={}) { if (!pool) return; const correlationId=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(requestId) ? requestId : randomUUID(); await pool.query("INSERT INTO audit_logs(tenant_id,actor_id,action,entity_type,entity_id,correlation_id,metadata) VALUES($1,$2,$3,$4,$5,$6,$7)",[tenantId,actorId,action,entityType,entityId,correlationId,metadata]); }
