  app.post("/api/v1/auth/login", async (request, reply) => { const body=safeBody(request.body); const tenantSlug=required(body.tenantSlug,"tenantSlug"), email=required(body.email,"email"), password=required(body.password,"password"); const p=await db(); const result=await p.query("SELECT u.id,u.email,u.display_name,u.password_hash,u.is_disabled,t.id tenant_id FROM users u JOIN tenants t ON t.id=u.tenant_id WHERE t.slug=$1 AND u.email=$2 AND u.deleted_at IS NULL",[tenantSlug,email]); const user=result.rows[0]; if (!user || user.is_disabled || !(await bcrypt.compare(password,user.password_hash))) { await audit(user?.tenant_id, user?.id,"auth.login_failed","user",user?.id,request.id); return reply.code(401).send({code:"invalid_credentials"}); } const permissions=(await p.query("SELECT DISTINCT p.code FROM permissions p JOIN role_permissions rp ON rp.permission_id=p.id JOIN user_roles ur ON ur.role_id=rp.role_id WHERE ur.user_id=$1 AND ur.tenant_id=$2",[user.id,user.tenant_id])).rows.map((r)=>r.code); const claims:Claims={sub:user.id,tenantId:user.tenant_id,email:user.email,permissions}; const accessToken=app.jwt.sign(claims,{expiresIn:"15m"}); const refreshToken=randomUUID()+randomUUID(); await p.query("INSERT INTO refresh_tokens(tenant_id,user_id,token_hash,expires_at) VALUES($1,$2,$3,now()+interval '30 days')",[user.tenant_id,user.id,hash(refreshToken)]); await audit(user.tenant_id,user.id,"auth.login_success","user",user.id,request.id); return {data:{accessToken,refreshToken,expiresIn:900,user:{id:user.id,email:user.email,displayName:user.display_name},permissions}}; });
